// These are NOT copies of the paid source questions or guaranteed live-exam items.
const D='Installation and Deployment',A='Administration',W='Workload Management',T='Troubleshooting and Optimization';
const AIO_MOCK_SETS=[[{"domain":"Installation and Deployment","stem":"A BCM administrator has discovered four new GPU nodes, but they lack the shared boot configuration. What is the most maintainable way to apply common node settings?","choices":["Assign the nodes to a suitable BCM category and verify inherited settings","Create four unrelated manual configurations","Configure the Slurm partition before the nodes boot","Change the Kubernetes namespace for the nodes"],"explain":"BCM categories provide a reusable configuration layer for nodes with similar roles and hardware."},{"domain":"Installation and Deployment","stem":"A compute node boots from an outdated operating-system image after maintenance. Which BCM configuration should be checked first?","choices":["The software image associated with its device or category","The priority of its last Slurm job","Its Kubernetes Service type","The number of DCGM exporter metrics"],"explain":"The assigned BCM software image determines the operating environment delivered to the node."},{"domain":"Installation and Deployment","stem":"You stage a new node category setting inside cmsh but other administrators cannot see it. What step is missing?","choices":["Commit the staged BCM configuration change","Run scancel on the node","Delete the default Kubernetes namespace","Restart the GPU without validating the configuration"],"explain":"BCM cmsh edits must be committed before they become persistent cluster configuration."},{"domain":"Installation and Deployment","stem":"Base View shows a node as unreachable after a provisioning change. Which evidence is most useful to check first?","choices":["Management-network connectivity and node provisioning state","Model inference accuracy on another cluster","A completed Slurm job from last week","A Docker image tag on an unrelated workstation"],"explain":"Provisioning and node reachability depend on the management path and correct node configuration."},{"domain":"Installation and Deployment","stem":"An operator must install Kubernetes on GPU hosts managed by BCM. What should be verified before installation?","choices":["Node readiness, networking, supported software images, and prerequisites","That all Slurm jobs are permanently deleted","That every node has the same GPU serial number","That Kubernetes namespaces were created on a laptop"],"explain":"Host readiness and platform prerequisites should be checked before introducing the Kubernetes control plane and workers."},{"domain":"Installation and Deployment","stem":"A datacenter wants repeatable firmware rollout across hundreds of nodes. What is the safest operational sequence?","choices":["Validate compatibility and rollback, stage changes, roll out in batches, and verify node health","Flash all devices simultaneously without inventory","Turn off monitoring and skip a change window","Change GPU settings until firmware warnings disappear"],"explain":"Firmware lifecycle work needs compatibility checks, staged deployment, rollback planning, and measured verification."},{"domain":"Installation and Deployment","stem":"A BlueField DPU must host an infrastructure service on its embedded processor. Which execution target fits the DOCA service model?","choices":["The DPU Arm environment with a compatible software stack","The Slurm controller database","The Kubernetes etcd snapshot","The GPU frame buffer used by CUDA kernels"],"explain":"DOCA services can run on the BlueField DPU Arm environment and interact with DPU capabilities."},{"domain":"Installation and Deployment","stem":"A new team should inspect cluster health in BCM without changing configurations. What control best supports that requirement?","choices":["Grant a role limited to the monitoring functions required","Share the BCM administrator credential with the team","Disable auditing for all cluster users","Assign root permissions for convenience"],"explain":"Role-based access limits privileges while preserving necessary visibility."},{"domain":"Installation and Deployment","stem":"An operations team needs an integrated platform for AI-cluster deployment, scheduling integration, monitoring, and recovery workflows. Which NVIDIA offering is designed for that scope?","choices":["NVIDIA Mission Control","NVIDIA Nsight Compute alone","A standalone Slurm squeue command","A container image registry alone"],"explain":"NVIDIA Mission Control integrates AI-factory management capabilities including BCM and workload orchestration."},{"domain":"Administration","stem":"An engineer needs a graphical overview of Slurm jobs, partitions, and nodes. Which tool is specifically designed for that purpose?","choices":["sview","sacct","sinfo","scancel"],"explain":"sview provides a graphical interface for Slurm administration and monitoring; the other tools are command-line utilities."},{"domain":"Administration","stem":"A Slurm node is DRAIN after a hardware incident. What should happen before an administrator resumes scheduling?","choices":["Resolve the cause, verify node health, then use the appropriate Slurm resume operation","Set State=RESUME immediately without investigation","Delete all Slurm accounts","Restart every Kubernetes pod in the datacenter"],"explain":"Nodes should return to service only after the condition that required draining has been addressed."},{"domain":"Administration","stem":"A scheduler administrator needs to inspect the configured CPUs, memory, GRES, and state of gpu-node04. Which command is suitable?","choices":["scontrol show node gpu-node04","squeue --me","kubectl get services","df -h /tmp"],"explain":"scontrol show node reports detailed Slurm node configuration and state."},{"domain":"Administration","stem":"An operator must review historical CPU time and exit status for completed Slurm jobs. What is the appropriate source?","choices":["sacct records, assuming accounting is configured","Kubernetes container image layers","BCM device categories alone","nvidia-smi process telemetry alone"],"explain":"sacct queries Slurm accounting for historical job outcomes and resource usage."},{"domain":"Administration","stem":"A Kubernetes cluster exposes eight GPUs on a node but a training pod requests more than are allocatable. What should the operator inspect?","choices":["The pod scheduling events and node allocatable extended resources","Only the GPU purchase receipt","Only the controller clock speed","Only the pod labels without its resource requests"],"explain":"Kubernetes scheduling depends on eligible nodes and their allocatable nvidia.com/gpu capacity."},{"domain":"Administration","stem":"A shared GPU must be divided into isolated compute and memory slices for independent applications. Which supported feature should be evaluated?","choices":["Multi-Instance GPU (MIG)","PCIe hot-plugging","Slurm array indexing","Kubernetes Service ClusterIP"],"explain":"On supported GPUs, MIG exposes partitioned GPU instances with defined compute and memory resources."},{"domain":"Administration","stem":"A team has read-only access to a Kubernetes namespace but cannot update Deployments. What should be examined?","choices":["RoleBindings and the permitted verbs in the associated RBAC Role or ClusterRole","Slurm GPU GRES configuration","Fabric Manager NVSwitch state","Docker overlay filesystem usage"],"explain":"Kubernetes RBAC controls API actions according to bound roles and permissions."},{"domain":"Workload Management","stem":"A training job waits with Reason=Resources even though the partition is UP. What is the most appropriate next step?","choices":["Compare the job's requested CPUs, GPUs, and memory with available eligible nodes","Reinstall the Slurm controller immediately","Delete the job accounting database","Rename the partition to production"],"explain":"A pending resource reason calls for checking requests against available scheduling resources and constraints."},{"domain":"Workload Management","stem":"A researcher has a batch script and wants Slurm to schedule it asynchronously. Which command is appropriate?","choices":["sbatch train.sh","squeue train.sh","sacct train.sh","sinfo train.sh"],"explain":"sbatch submits a batch script for scheduling and later execution."},{"domain":"Workload Management","stem":"A Kubernetes inference Deployment fails with ImagePullBackOff immediately after a tag change. What is the best first diagnostic action?","choices":["Inspect the pod events for the exact registry or image-pull error","Drain every GPU node","Modify the Slurm partition configuration","Force GPU MIG mode on every host"],"explain":"Pod events can reveal missing tags, registry authentication failures, or network problems."},{"domain":"Workload Management","stem":"A pod requires one NVIDIA GPU and currently lands on CPU-only nodes. Which resource declaration should be checked?","choices":["A GPU extended resource limit such as nvidia.com/gpu: 1","A Service of type NodePort","A Slurm job time limit","A BCM node image hash"],"explain":"GPU workloads use the NVIDIA extended resource in their Kubernetes pod specification."},{"domain":"Workload Management","stem":"A Slurm training job requires two GPUs per node and runs on nodes with properly configured GRES. Which request expresses that requirement?","choices":["--gres=gpu:2","--mem=2G for every GPU","--ntasks=2 without a GPU request","--exclusive=false only"],"explain":"Slurm GPU generic resources can be requested with the --gres option when the cluster is configured accordingly."},{"domain":"Workload Management","stem":"An AI platform team must limit one group's GPU consumption independently of other groups. Which Run:ai construct is most relevant?","choices":["Team or project resource allocation policies with quotas","A single shared Docker root password","A change to the GPU board serial number","Disabling Kubernetes namespaces globally"],"explain":"Run:ai provides workload scheduling and resource-allocation controls for organizational groups."},{"domain":"Workload Management","stem":"A pod shows Running, but an inference endpoint still times out. What should be validated next?","choices":["Pod readiness, application logs, endpoints, and service connectivity","Whether the GPU has an attractive model name","Whether all Slurm jobs have finished","Whether the registry tag has uppercase letters"],"explain":"Container Running state does not guarantee application readiness or network reachability."},{"domain":"Troubleshooting and Optimization","stem":"A GPU workload fails intermittently and the host logs include NVIDIA Xid entries. What is the best diagnostic approach?","choices":["Correlate Xid codes with DCGM or nvidia-smi telemetry and workload timing","Immediately replace every GPU in the rack","Ignore driver messages if utilization is low","Reset the cluster without retaining logs"],"explain":"Driver error codes must be interpreted with hardware, software, and workload context."},{"domain":"Troubleshooting and Optimization","stem":"An NVSwitch system reports fabric initialization failures after a service restart. Which service should be inspected?","choices":["NVIDIA Fabric Manager and its logs","Kubernetes CoreDNS only","Slurm accounting daemon only","The container registry index"],"explain":"Fabric Manager coordinates NVSwitch fabric management on supported systems."},{"domain":"Troubleshooting and Optimization","stem":"A container fails to start with a missing CUDA library. Which compatibility relationship should be investigated?","choices":["The container CUDA stack, NVIDIA host driver, and runtime integration","The pod name length and capitalization","The Slurm partition description","The BCM web interface theme"],"explain":"CUDA-enabled containers depend on compatible host drivers and correctly configured runtime access."},{"domain":"Troubleshooting and Optimization","stem":"A training pipeline achieves high GPU utilization but poor throughput while reading samples. Which metrics should be collected?","choices":["Storage read latency, throughput, and data-loader wait time","Only GPU temperature at idle","Only Kubernetes service names","Only the number of users in BCM"],"explain":"Slow data delivery can bottleneck overall training despite periods of high GPU utilization."},{"domain":"Troubleshooting and Optimization","stem":"An operator suspects a full filesystem on a training node. Which command directly reports filesystem usage by mounted volume?","choices":["df -h","squeue -u","kubectl get roles","nvidia-smi --query-compute-apps"],"explain":"df -h reports capacity and use for mounted filesystems."},{"domain":"Troubleshooting and Optimization","stem":"A Slurm node is unexpectedly DOWN. Which logs are most relevant to local daemon failures?","choices":["systemctl status slurmd and journalctl -u slurmd","kubectl logs kube-proxy from another cluster","sacct on an unrelated user","NVIDIA NGC model descriptions"],"explain":"The slurmd unit state and logs help identify node-agent failures."},{"domain":"Troubleshooting and Optimization","stem":"An operator must diagnose GPU health without relying solely on instantaneous utilization. Which toolkit offers health checks and diagnostic tests?","choices":["NVIDIA DCGM","Kubernetes ingress-nginx","The Slurm GUI alone","Docker Hub search"],"explain":"DCGM provides GPU telemetry and diagnostics for operational monitoring."}],[{"domain":"Installation and Deployment","stem":"A new BCM-managed worker has the correct IP address but cannot PXE-boot its expected image. Which dependency should be checked?","choices":["Boot services, network path, and the node's assigned software image","A completed Run:ai training job","Kubernetes HPA threshold values","The GPU temperature on another host"],"explain":"BCM provisioning depends on reachable boot services and a valid node image assignment."},{"domain":"Installation and Deployment","stem":"BCM administrators manage nodes in two cloud providers with different identities. What is the soundest configuration practice?","choices":["Maintain provider-specific authentication settings with appropriate credentials and permissions","Assume one access token automatically works for all providers","Copy unprotected root passwords into every node definition","Disable identity checks for faster provisioning"],"explain":"Distinct clouds require correctly configured provider access and a least-privilege approach."},{"domain":"Installation and Deployment","stem":"A BCM configuration is edited but the affected nodes do not show the new setting. What should be checked before reinstalling nodes?","choices":["Whether the change was committed and synchronized to the intended nodes","Whether the GPU memory is full","Whether the Slurm job name is lowercase","Whether a Kubernetes Secret contains a certificate from another service"],"explain":"Staged, committed, and applied configuration states must be distinguished."},{"domain":"Installation and Deployment","stem":"A site needs a central operational view of GPU utilization and unhealthy nodes. Which BCM capability is most directly relevant?","choices":["Base View performance and node-health monitoring","scancel --signal on user jobs","kubectl edit configmap on a workstation","A private container registry alone"],"explain":"Base View is BCM's interface for cluster observability and operational management."},{"domain":"Installation and Deployment","stem":"After adding new GPU nodes, BCM discovers incorrect interface assignments. What is the appropriate corrective strategy?","choices":["Review node network settings and apply the correct management and data interfaces","Reset the GPUs without checking network addresses","Change the Slurm account quotas","Rename all Kubernetes Pods"],"explain":"Interface configuration must match the physical and logical cluster network topology."},{"domain":"Installation and Deployment","stem":"An AI factory already uses BCM and needs integrated workflow orchestration and observability across its cluster. Which solution addresses the broader stack?","choices":["NVIDIA Mission Control","The Slurm sinfo command alone","A GPU thermal sensor alone","A Docker image tag alone"],"explain":"Mission Control brings together cluster management, workload integration, and operational observability."},{"domain":"Installation and Deployment","stem":"A DPU service fails to initialize immediately after deployment. Which prerequisite deserves attention?","choices":["Compatible DPU firmware, OS or BSP components, and service dependencies","The Slurm GUI layout","The number of CoreDNS replicas on unrelated nodes","The training team's model architecture"],"explain":"DPU services require compatible platform components and reachable service dependencies."},{"domain":"Installation and Deployment","stem":"You are asked to deploy GPU Operator as part of Kubernetes GPU enablement. Which result demonstrates its intended purpose?","choices":["Kubernetes GPU drivers and device components become managed and discoverable as appropriate","Slurm controller installation becomes unnecessary","GPU Operator provides physical rack cabling","Kubernetes stops enforcing RBAC"],"explain":"GPU Operator manages GPU-enabling Kubernetes components according to its deployment configuration."},{"domain":"Installation and Deployment","stem":"A newly provisioned BCM category is intended for GPU nodes only. What should be validated before assigning devices?","choices":["That its image, driver stack, and inherited GPU-related settings match the hardware","That all CPU-only nodes inherit the same GPU settings","That every node has the same MAC address","That no node will ever need maintenance"],"explain":"Category definitions must fit actual node roles to avoid incompatible inherited configuration."},{"domain":"Administration","stem":"An administrator wants to view and modify Slurm jobs graphically. Which tool is most suitable?","choices":["sview","sacct","sinfo","sreport"],"explain":"sview is Slurm's graphical job and node administration interface."},{"domain":"Administration","stem":"Slurm accounting is enabled and a researcher has exceeded an association limit. Which configuration area should be investigated?","choices":["The account association or QOS policy managed through sacctmgr","A Kubernetes image tag","The Fabric Manager service","The GPU model naming convention"],"explain":"Slurm accounts, associations, and QOS can impose resource and scheduling limits."},{"domain":"Administration","stem":"A firewall HA pair must preserve existing sessions during a failover. What must the solution synchronize?","choices":["Configuration and active session state over an appropriate failover or heartbeat link","Only system clocks","Only an annual configuration backup","GPU utilization statistics"],"explain":"Stateful failover requires synchronized policies and session data, not just equivalent device configurations."},{"domain":"Administration","stem":"A Kubernetes administrator must let an application access only its own namespace resources. Which identity and authorization objects are relevant?","choices":["A ServiceAccount plus suitable Role and RoleBinding","A global cluster-admin token embedded in the image","Slurm scontrol and sacct only","An NGC repository tag"],"explain":"Namespaced service identities and role bindings can enforce limited Kubernetes API access."},{"domain":"Administration","stem":"A team wants GPU nodes reserved for training pods, while CPU-only services use other nodes. Which placement mechanism helps?","choices":["Node taints on GPU hosts with matching tolerations for approved workloads","Disable networking on all GPU hosts","Apply ResourceQuota to the kube-system namespace only","Configure Slurm GRES on the control-plane node only"],"explain":"Kubernetes taints repel pods unless they declare matching tolerations; other scheduling constraints may also be needed."},{"domain":"Administration","stem":"A Kubernetes team wants to see why an existing pod is Pending. Which command provides scheduling events?","choices":["kubectl describe pod POD -n NAMESPACE","kubectl get namespaces --show-labels","docker image prune -a","sacctmgr show users"],"explain":"Pod descriptions include events and scheduling errors reported by Kubernetes."},{"domain":"Administration","stem":"An A100 is in MIG mode and multiple applications require guaranteed isolated slices. What should determine the chosen profile?","choices":["Each application's GPU memory and compute requirements relative to supported MIG instance profiles","Only the order containers were launched","Only the host CPU socket count","The shortest possible Kubernetes namespace"],"explain":"MIG profiles define hardware-partitioned compute and memory resources on supported GPUs."},{"domain":"Workload Management","stem":"A job submission is pending because no node satisfies its specified partition and GPU request. What should be compared?","choices":["The job's requested GRES and partition against eligible node resources","Only the job owner's home directory size","Only the client workstation hostname","Only the Slurm GUI window dimensions"],"explain":"Placement depends on partition eligibility, available GRES, and other requested resources."},{"domain":"Workload Management","stem":"A researcher asks for one interactive GPU session instead of a batch script. Which Slurm tool fits interactive execution?","choices":["srun with an appropriate allocation and GPU request","sacct to erase historical jobs","sview to replace the workload executable","sinfo to download a container"],"explain":"srun can launch parallel or interactive work, with resources allocated by Slurm."},{"domain":"Workload Management","stem":"A model-serving pod is stuck pulling a private NGC image. What should be verified?","choices":["Image reference and registry credentials available to the pod","The Slurm node drain reason only","A host's desktop wallpaper","The cluster's DNS name length alone"],"explain":"Image pulls require a valid image reference, registry reachability, and appropriate credentials for private repositories."},{"domain":"Workload Management","stem":"A Deployment update introduced an unhealthy image, and Kubernetes retains a previous working revision. Which controlled recovery is appropriate?","choices":["Inspect rollout history and roll back to a verified healthy revision","Force deletion of every namespace","Run scontrol update State=DOWN for all nodes","Change GPU firmware without troubleshooting"],"explain":"Deployment rollout history supports controlled rollback when an earlier ReplicaSet is still available."},{"domain":"Workload Management","stem":"Two teams share GPU nodes but require independent namespace-wide resource ceilings. Which Kubernetes resource is designed to cap aggregate usage?","choices":["ResourceQuota in each namespace","A ClusterIP Service","A ConfigMap containing GPU serial numbers","A Slurm accounting report alone"],"explain":"Kubernetes ResourceQuota constrains aggregate consumption of selected resources in a namespace."},{"domain":"Workload Management","stem":"An inference workload runs but a scheduler reports unsatisfied node affinity. What is the proper next investigation?","choices":["Inspect pod affinity rules and candidate node labels","Reinstall the GPU driver immediately","Reset the Slurm controller","Remove all cluster audit events"],"explain":"Node affinity restricts pods to nodes whose labels match the specified expressions."},{"domain":"Workload Management","stem":"A Slurm batch job completes but its application exits nonzero. Which record best supports diagnosis?","choices":["Job accounting status together with captured stdout and stderr","The cluster dashboard screenshot alone","Only the image repository name","A list of every Kubernetes namespace"],"explain":"Scheduler records and application output help distinguish scheduling success from application failure."},{"domain":"Troubleshooting and Optimization","stem":"A GPU node's Kubernetes device plugin is healthy but the scheduler advertises zero allocatable GPUs. What next?","choices":["Inspect node conditions, driver visibility, plugin logs, and resource registration","Assume the GPU count will recover without checking","Delete the entire cluster configuration","Change Slurm job time limits"],"explain":"Device discovery and Kubernetes resource advertisement should be traced through the GPU stack."},{"domain":"Troubleshooting and Optimization","stem":"A Docker container fails with a runtime error before an application starts. Where should troubleshooting begin?","choices":["Container runtime logs, launch options, and NVIDIA runtime configuration","Slurm partition names only","BCM report templates","The application's output dataset size"],"explain":"Pre-start failures are usually diagnosed at the container runtime and platform integration layers."},{"domain":"Troubleshooting and Optimization","stem":"A GPU host reports correct memory capacity but elevated corrected-memory error counts over time. What is the sensible response?","choices":["Review DCGM or driver telemetry trends and apply the documented maintenance policy","Ignore errors because memory capacity is unchanged","Delete Kubernetes service accounts","Change the user-facing job names"],"explain":"Error trends matter even when a device remains accessible."},{"domain":"Troubleshooting and Optimization","stem":"A training workload suffers slow remote-storage reads with otherwise healthy GPUs. Which measurement isolates the bottleneck?","choices":["Storage throughput and latency under the workload's access pattern","The number of Pods in kube-system only","The rack's total number of GPUs","The command-line shell prompt"],"explain":"Sustained reads and latency indicate storage service and data pipeline limitations."},{"domain":"Troubleshooting and Optimization","stem":"Nodes intermittently lose fabric communication after a network change. Which evidence is useful?","choices":["Link counters, topology, error logs, and affected traffic paths","Only the model training epochs","Only the number of cloud accounts","Only the container image creation date"],"explain":"Network failures are analyzed using topology and link-level telemetry together with scope and timing."},{"domain":"Troubleshooting and Optimization","stem":"A container can see a GPU but memory allocation fails under load. What should be checked?","choices":["Available GPU memory, competing processes, and workload allocation requirements","Slurm account names only","Whether the pod uses a memorable label","Whether the cluster hosts a web dashboard"],"explain":"GPU out-of-memory conditions require examining allocation pressure and workload sizing."},{"domain":"Troubleshooting and Optimization","stem":"A repaired Slurm node has returned to IDLE. What verification demonstrates the service is usable?","choices":["Confirm node health and run a small permitted test job","Assume no validation is required once IDLE appears","Remove every other node from the partition","Disable Slurm logging"],"explain":"End-to-end validation confirms that a healthy scheduler state translates into functioning workloads."}],[{"domain":"Installation and Deployment","stem":"A BCM operator has registered a GPU-capable bare-metal node but it is missing driver dependencies. What should be verified before provisioning it again?","choices":["The selected software image contains a validated driver and OS stack for that GPU model","The Slurm job priority is set to maximum","A Kubernetes Service uses LoadBalancer","GPU memory is manually overclocked"],"explain":"Provisioning correctness depends on compatible node images and role-specific dependencies."},{"domain":"Installation and Deployment","stem":"A cloud extension configured through BCM fails to discover machines in one provider. What is the most relevant first check?","choices":["That provider's credentials, API permissions, and connection settings","The host GPU temperature","The number of pod replicas in an unrelated namespace","The Slurm accounting retention period"],"explain":"Cloud integration requires valid provider identity and reachable management APIs."},{"domain":"Installation and Deployment","stem":"An administrator edits a GPU node category but newly provisioned nodes remain inconsistent. Which BCM workflow is appropriate?","choices":["Verify inheritance, commit the intended configuration, synchronize the image, and validate nodes","Rename the node and immediately declare success","Delete all BCM categories","Ignore the discrepancy until the next yearly upgrade"],"explain":"Configuration changes need consistent assignment, application, and verification across managed nodes."},{"domain":"Installation and Deployment","stem":"You want BCM to install and operate Kubernetes on a group of NVIDIA nodes. What is a prerequisite for reliable node onboarding?","choices":["Correct host images, management connectivity, container runtime, and Kubernetes configuration","A permanent Slurm DOWN state on every host","A GPU MIG profile assigned to the control plane","Every node running a different unsupported driver"],"explain":"Control-plane and worker provisioning depend on compatible software and reachable hosts."},{"domain":"Installation and Deployment","stem":"A team must roll out GPU Operator components to a fresh cluster. What should it validate after installation?","choices":["Operator-managed Pods are healthy and GPU resources are exposed on intended nodes","Every user has cluster-admin access","The Slurm queue is empty regardless of workload","All container image credentials are public"],"explain":"Operator health and resource discovery are necessary before scheduling GPU workloads."},{"domain":"Installation and Deployment","stem":"A new DOCA service is being deployed to BlueField devices. Which environmental compatibility question matters most?","choices":["Whether the DPU platform software and DOCA version support the service","Whether the GPU has enough MIG slices","Whether Slurm job IDs are consecutive","Whether a namespace name is short"],"explain":"DOCA applications rely on supported hardware, firmware, and software combinations."},{"domain":"Installation and Deployment","stem":"A large AI cluster requires coordinated provisioning, job scheduling integration, observability, and recovery policies. What NVIDIA software layer addresses this operational scope?","choices":["NVIDIA Mission Control","Only NVIDIA Nsight Systems","Only a Docker image registry","Only one Slurm login node"],"explain":"Mission Control integrates cluster operations with management, workload orchestration, and monitoring components."},{"domain":"Installation and Deployment","stem":"After installing Slurm, no nodes register with the scheduler. What is the most relevant configuration area to validate?","choices":["slurmctld and slurmd connectivity plus consistent node/resource definitions","A Kubernetes deployment's replica count","The model checkpoint frequency","The NGC image owner"],"explain":"Slurm requires consistent configuration, controller connectivity, and running node daemons."},{"domain":"Installation and Deployment","stem":"A maintenance window includes GPU firmware updates and a BCM image change. What should the operations report retain?","choices":["Versions, affected hosts, change procedure, verification findings, and rollback instructions","Only a statement that installation completed","Only the trainer's name","Only the count of pending Slurm jobs"],"explain":"Accurate change records enable auditability and safe remediation if an update regresses service."},{"domain":"Administration","stem":"A Kubernetes GPU pool should be unavailable to regular application pods but available to approved training pods. Which controls achieve this?","choices":["GPU-node taints with tolerations on approved training Pods and suitable node selection","Only a cluster-wide application label","Restart kubelet after every submission","Remove the NVIDIA device plugin"],"explain":"Taints and tolerations repel nonmatching pods; node selection ensures approved workloads reach the intended pool."},{"domain":"Administration","stem":"A system administrator wants to inspect Slurm partition limits before changing them. Which command family is most appropriate?","choices":["scontrol show partition and the corresponding configuration","kubectl get ingressclasses","docker image inspect of a random image","dcgmi diag on an unrelated GPU"],"explain":"Slurm partition definitions and restrictions are visible through scheduler configuration tools."},{"domain":"Administration","stem":"A Slurm job requests four GPUs but is queued indefinitely. Which additional policy information can explain the wait even when GPUs exist?","choices":["Account limits, QOS, reservations, and partition eligibility","The Kubernetes Service port number","The cloud provider logo","The Base View browser language"],"explain":"Scheduling considers resource availability alongside policy and reservation constraints."},{"domain":"Administration","stem":"An A100 with MIG enabled must support inference instances with bounded memory allocations. What governs the instance shapes?","choices":["Hardware-supported MIG profiles with defined GPU and memory slices","Arbitrary percentages specified by a Docker environment variable","CPU pinning of the CUDA process alone","The Kubernetes image registry hostname"],"explain":"MIG instance profiles define supported resource partitions; arbitrary values cannot be requested as hardware instances."},{"domain":"Administration","stem":"A Kubernetes operator needs to confirm which GPU resources the scheduler can assign. Which node field is decisive?","choices":["status.allocatable for nvidia.com/gpu","metadata.creationTimestamp alone","A ConfigMap containing a GPU model description","The Pod's latest stdout log"],"explain":"Kubernetes schedules extended resources based on allocatable node capacity."},{"domain":"Administration","stem":"A security policy requires a service to read Pods but not modify Deployments. What is the appropriate configuration?","choices":["An RBAC Role granting only needed read verbs, bound to its ServiceAccount","A cluster-admin ClusterRoleBinding for all accounts","Slurm admin privileges on every node","A public Docker registry"],"explain":"Kubernetes RBAC can authorize specific verbs on specific API resources."},{"domain":"Administration","stem":"A Slurm node is DRAIN after an Xid alert but its hardware passes subsequent checks. How should it return to service?","choices":["Document the fault resolution, apply RESUME through scontrol, then verify placement","Change its state to RESUME without examining the alert","Recreate every user account","Change GPU clock policy blindly"],"explain":"Restoring a drained node is appropriate only after the triggering condition is resolved and verified."},{"domain":"Workload Management","stem":"An application requires one whole GPU but the Kubernetes scheduler reports insufficient nvidia.com/gpu. What should be compared?","choices":["Pod resource limits and the allocatable GPU resources on eligible nodes","Only the Service's external IP","Only the Slurm partition description","Only the GPU serial-number format"],"explain":"Extended GPU requests must fit the inventory advertised to the Kubernetes scheduler."},{"domain":"Workload Management","stem":"A training job must run only on GPU nodes in the ai partition. Which Slurm parameters are relevant?","choices":["The intended partition and a matching GPU resource request","Only the output filename","Only the Kubernetes namespace name","Only the container creation timestamp"],"explain":"Slurm partition selection and GPU GRES or supported GPU options constrain placement."},{"domain":"Workload Management","stem":"A user tries to deploy a private NGC inference image, but image pulling returns unauthorized. What should be checked?","choices":["Registry credentials or image pull secrets and image access permissions","The Slurm controller uptime only","GPU power draw at idle only","BCM web interface permissions only"],"explain":"Authentication failures during image pulling point to registry access, secrets, or repository authorization."},{"domain":"Workload Management","stem":"A developer schedules a Pod onto the wrong GPU class. Which Kubernetes primitives can express the intended hardware pool?","choices":["Node labels with appropriate nodeSelector or node affinity","A Service selector without node constraints","A Slurm job account on a different cluster","The Dockerfile filename"],"explain":"Kubernetes node selection is controlled by node labels and Pod scheduling constraints."},{"domain":"Workload Management","stem":"The GPU cluster must prioritize one team's inference traffic while protecting batch training capacity. Which policy is most relevant in a Run:ai-managed environment?","choices":["Project allocations, quotas, and supported workload scheduling priorities","Disabling all Kubernetes quotas permanently","Giving each application an administrator account","Changing physical GPU part numbers"],"explain":"Run:ai supports group-level resource allocation and workload scheduling policies."},{"domain":"Workload Management","stem":"A Slurm training batch job launches in a container using a supported Pyxis/Enroot integration. What should be verified if the container fails before training starts?","choices":["Container image availability, plugin configuration, mounts, and runtime logs","The Kubernetes Service type for another app","The BCM node naming pattern alone","The rack power budget spreadsheet alone"],"explain":"Containerized Slurm execution depends on the image, integration, filesystem access, and runtime configuration."},{"domain":"Workload Management","stem":"A Deployment update creates Pods that are Running but not Ready. Which Kubernetes command helps establish rollout health?","choices":["kubectl rollout status deployment/NAME with pod readiness inspection","kubectl delete node on every worker","sinfo -R only","cmsh commit without reviewing changes"],"explain":"Deployment rollout status tracks progress and whether updated replicas satisfy readiness requirements."},{"domain":"Troubleshooting and Optimization","stem":"A GPU application using GPUDirect Storage has lower throughput than expected. What should be investigated?","choices":["Magnum IO or GDS configuration, storage path capabilities, and observed I/O throughput","Only the Kubernetes namespace spelling","Only the Slurm job ID width","Only the CPU model release year"],"explain":"GDS performance depends on a compatible software and storage path and actual I/O behavior."},{"domain":"Troubleshooting and Optimization","stem":"A node periodically reports GPU faults but returns to service after reboot. What is the strongest maintenance decision input?","choices":["Repeated error history, DCGM diagnostics, driver logs, and workload impact","The most recent command typed by a user alone","The cabinet paint color","The presence of an unrelated ConfigMap"],"explain":"Recurring faults require evidence across incidents rather than assuming a reboot resolved the root cause."},{"domain":"Troubleshooting and Optimization","stem":"A GPU-hosted service shows low utilization despite a deep inference request queue. Which cause should be ruled out first?","choices":["CPU preprocessing, batching, data movement, and scheduling bottlenecks","That the GPU manufacturer logo is missing","That Slurm accounting lacks color coding","That a BCM report uses old fonts"],"explain":"Low GPU utilization can reflect bottlenecks outside the accelerator computation."},{"domain":"Troubleshooting and Optimization","stem":"A compute node is Ready but GPU workloads remain Pending. Which chain should be investigated?","choices":["GPU driver, device plugin advertising, node allocatable capacity, and Pod events","Only the node's Ready Boolean","Only controller disk capacity","Only the container image description"],"explain":"Host readiness does not guarantee that GPU extended resources are correctly advertised."},{"domain":"Troubleshooting and Optimization","stem":"Slurm reports a node has fewer GPU GRES than physically installed. What should be compared?","choices":["Physical GPU inventory and Slurm GRES detection and configuration","Kubernetes namespace counts","Storage block size only","The last NGC container tag used"],"explain":"Slurm resource discrepancies can arise from mismatched GRES definitions or GPU detection."},{"domain":"Troubleshooting and Optimization","stem":"A Docker image starts locally but fails on a cluster GPU host. Which environmental difference matters?","choices":["Host driver and NVIDIA container runtime setup on the cluster node","Local terminal font selection","The user's preferred Slurm job title","The model's marketing description"],"explain":"GPU container execution depends on compatible host software and configured runtime access."},{"domain":"Troubleshooting and Optimization","stem":"An administrator must distinguish memory pressure from GPU compute saturation. Which instrumentation helps?","choices":["GPU memory and utilization telemetry alongside CPU and application metrics","Only the count of running Kubernetes Services","Only the Slurm controller hostname","Only the cluster access policy description"],"explain":"Comparative telemetry exposes whether compute, memory, or upstream stages are limiting performance."}],[{"domain":"Installation and Deployment","stem":"A DGX cluster is being brought under BCM management and node health varies across racks. What is the best first operational action?","choices":["Check deployment state, image alignment, management connectivity, and per-node health in BCM","Reflash every GPU at once without diagnostics","Remove all Slurm accounts to clear the queue","Launch a large production workload as a health check"],"explain":"A managed cluster must establish consistent provisioning and basic reachability before production use."},{"domain":"Installation and Deployment","stem":"A new AI factory needs BCM provisioning alongside workload management, observability, and automated operations. Which NVIDIA platform combines those layers?","choices":["NVIDIA Mission Control","A standalone squeue invocation","The CUDA compiler alone","An NGC container repository alone"],"explain":"NVIDIA Mission Control brings together infrastructure management, workload scheduling integration, and operational monitoring."},{"domain":"Installation and Deployment","stem":"A GPU node was reimaged and its management interface is no longer reachable. Which evidence should be checked?","choices":["BCM interface and address configuration, DHCP or network boot path, and switch port status","The training dataset labels","The number of MIG profiles requested by users","The Slurm job accounting archive"],"explain":"Loss of management connectivity is diagnosed at the provisioning and network layers."},{"domain":"Installation and Deployment","stem":"Before rolling a new node software image across a Slurm partition, what is the best method?","choices":["Drain appropriate nodes, validate a canary image, roll out in controlled batches, and verify them before resuming","Replace all active nodes without draining","Modify every job priority to maximum","Turn off image version tracking"],"explain":"Safe rolling maintenance coordinates scheduler isolation with software-image lifecycle and validation."},{"domain":"Installation and Deployment","stem":"A BCM deployment must support fault tolerance in its management layer. Which design consideration is essential?","choices":["Documented high-availability topology, state or service continuity, and tested failover procedures","A single management host without backups or recovery procedures","A Kubernetes Service name with extra characters","A larger number of Slurm queued jobs"],"explain":"HA requirements need explicit redundancy and failover testing rather than assuming every service is redundant."},{"domain":"Installation and Deployment","stem":"An operations team wants to quantify recurring node outages through BCM. Which feature set best addresses that?","choices":["Monitoring, historical events, and generated operational reports","Only the GPU model name","Only the Docker container hostname","Only the last Slurm job name"],"explain":"BCM monitoring and reporting help track reliability, resource use, and recurring issues."},{"domain":"Installation and Deployment","stem":"A site's Run:ai integration is being installed onto its Kubernetes cluster. Which prerequisites deserve verification?","choices":["Compatible Kubernetes environment, GPU enablement, access permissions, and supported integration requirements","A separate BIOS image for every namespace","Permanent removal of kubelet","No resource information for nodes"],"explain":"Workload scheduling integrations depend on a functioning Kubernetes platform and suitable accelerator support."},{"domain":"Installation and Deployment","stem":"A BlueField DPU provides an offload path for infrastructure services. What should deployment validation include?","choices":["Service health, DPU network access, supported DOCA stack, and observed function","Only an available Slurm job slot","Only GPU fan RPM","Only the Kubernetes cluster name"],"explain":"Infrastructure services on DPUs require operational and functional verification, not just successful package installation."},{"domain":"Installation and Deployment","stem":"A new GPU partition is added to the cluster and customers are waiting for access. Which information must be validated before enabling it?","choices":["Accurate node inventory, scheduler configuration, permissions, and end-to-end test placement","The personal monitor resolution of every user","The marketing name of each AI model","A Docker Hub account for each node"],"explain":"Scheduler enablement should follow correct resources, policy, and verified workload placement."},{"domain":"Administration","stem":"An operator sees one Slurm node in DRAIN while the rest are IDLE. Which command best identifies the recorded drain reason?","choices":["sinfo -R or scontrol show node for that node","kubectl get pods in a different cluster","nvidia-smi -L on the controller only","docker images --digests on the login node"],"explain":"Slurm records drain reasons in scheduler node state and reason reporting."},{"domain":"Administration","stem":"A team wants to allocate GPU compute capacity to several Slurm users with different service levels. Which control is relevant?","choices":["Accounts, associations, QOS, and partition policy","Kubernetes Service ClusterIP values alone","Fabric Manager topology files alone","NGC registry names alone"],"explain":"Slurm scheduling policies can be assigned through accounts, QOS, and partition configuration."},{"domain":"Administration","stem":"A workload administrator must determine why a Kubernetes Pod cannot schedule. Which evidence is most directly actionable?","choices":["Scheduler events from kubectl describe pod and eligible-node resources","Only the Pod's container image digest","Only the count of services in the namespace","Only the Slurm node daemon uptime"],"explain":"Scheduling events identify constraints and resource shortages that block Pod placement."},{"domain":"Administration","stem":"A managed GPU node provides multiple MIG instances. What must the Kubernetes device layer advertise for Pods to request those slices?","choices":["The supported MIG extended resource types and available counts","One arbitrary fraction declared in Pod annotations","The complete physical node as a single ConfigMap","Only the Slurm partition name"],"explain":"Kubernetes schedules GPU or MIG allocations using resources advertised by the device plugin."},{"domain":"Administration","stem":"An admin needs to inspect a specific Slurm job's submitted resource request and pending reason. Which command is appropriate?","choices":["scontrol show job JOBID","kubectl logs on an unrelated namespace","cmsh show users without filters","nv-fabricmanager --version only"],"explain":"scontrol show job reveals details of an active Slurm job and its scheduling constraints."},{"domain":"Administration","stem":"An administrator must investigate Kubernetes access denied errors without granting broad privileges. What should be inspected?","choices":["The requesting identity and applicable RBAC RoleBindings or ClusterRoleBindings","The GPU power limit first","A new NGC image tag first","The Slurm node count only"],"explain":"Authorization failures should be matched to the user's effective permissions and required API verbs."},{"domain":"Administration","stem":"An inference team needs reliable GPU partition isolation. Which method is appropriate on a compatible GPU?","choices":["Configured MIG instances mapped to workload resource requests","Overcommitting every Pod without admission controls","Using CPU cgroups as the only GPU isolation mechanism","Increasing GPU fan speed automatically"],"explain":"MIG provides hardware-backed partitions with supported resource profiles on compatible accelerators."},{"domain":"Workload Management","stem":"A Kubernetes inference pod stays Pending due to an untolerated GPU-node taint. What change is appropriate after confirming the placement policy?","choices":["Add the specifically authorized matching toleration and required node selector or affinity","Delete all node taints in the cluster without review","Grant cluster-admin to the Pod","Set Slurm State=RESUME on every node"],"explain":"Targeted tolerations permit approved pods to use intentionally tainted GPU nodes."},{"domain":"Workload Management","stem":"A researcher needs GPU resources for only a short interactive analysis. Which Slurm workflow is suitable?","choices":["Request an interactive allocation through salloc or an appropriate srun command","Run sacctmgr modify cluster without authorization","Delete the partition to free capacity","Change the Base View theme"],"explain":"Slurm supports interactive allocations in addition to scheduled batch scripts."},{"domain":"Workload Management","stem":"A long training workload has failed, and the team needs its exit code plus recorded resource usage. Which command is suited to post-run investigation?","choices":["sacct for the specified job and configured accounting fields","sinfo alone","kubectl get services alone","dcgmi diag alone"],"explain":"sacct reports historical job states and accounting usage when the accounting service is configured."},{"domain":"Workload Management","stem":"A GPU training Pod requests eight GPUs from a node advertising only four allocatable GPUs. What is the immediate scheduling outcome?","choices":["The Pod cannot schedule on that node until its request fits an eligible node","Kubernetes automatically splits the single Pod across nodes","The GPU Operator creates four new physical GPUs","The Slurm controller allocates the difference automatically"],"explain":"Kubernetes schedules a Pod's requested extended resources on a qualifying node; it does not split an individual Pod's GPU request among nodes."},{"domain":"Workload Management","stem":"An NGC container is available in a public registry but fails to start after pulling successfully. What should be investigated next?","choices":["Startup logs, application entrypoint, runtime options, and GPU visibility","Credentials for the already completed pull as the only possibility","The Slurm partition name alone","The rack's label design"],"explain":"Image retrieval success is distinct from container process startup and accelerator access."},{"domain":"Workload Management","stem":"A team has a strict GPU allocation budget for its training namespace. Which Kubernetes policy object can bound its aggregate GPU resource use?","choices":["ResourceQuota configured for the relevant GPU extended resource","A Service of type ExternalName","An unlabeled Pod with no limits","A Dockerfile ARG with a team name"],"explain":"Namespace ResourceQuota can enforce aggregate limits for extended resources when properly configured."},{"domain":"Workload Management","stem":"A Run:ai deployment must distribute resources fairly between interactive and batch workloads. Which capability is most relevant?","choices":["Platform scheduling and project resource policies","A static Docker host mapping alone","Replacing Kubernetes with plain SSH","Disabling all scheduling priorities"],"explain":"Run:ai supports orchestrated allocation and scheduling policies across AI workloads."},{"domain":"Troubleshooting and Optimization","stem":"A node's GPU disappears from nvidia-smi following a driver update. Which investigation path is best?","choices":["Inspect driver/module loading, PCIe detection, firmware compatibility, and system logs","Change Kubernetes namespace names","Reboot the Slurm controller before checking the host","Modify all workload image tags"],"explain":"Device disappearance after a driver change calls for host-level enumeration and driver diagnostics."},{"domain":"Troubleshooting and Optimization","stem":"An application intermittently fails GPU-to-GPU communication on an NVSwitch system. What is the useful first layer of diagnosis?","choices":["Fabric Manager status, topology, NVLink health, and reported errors","Only the GPU model's marketing specifications","Only the Slurm accounting database size","Only the number of Kubernetes Services"],"explain":"Fabric and peer-communication problems require a view of the management service and physical or logical interconnect health."},{"domain":"Troubleshooting and Optimization","stem":"A large-model training job runs slowly even with healthy GPUs. The storage system reports high read latency. Which action is justified?","choices":["Profile the data pipeline and storage I/O path before changing GPU settings","Immediately overclock all GPUs","Increase Slurm job priority without investigation","Disable all error logging"],"explain":"High storage latency can starve GPU workloads; profile before optimizing the wrong layer."},{"domain":"Troubleshooting and Optimization","stem":"A GPU node emits frequent PCIe-related errors. Which evidence should inform whether to isolate it?","choices":["System and driver logs, error counters, affected workloads, and repeatability","Only the hostname character count","Only an unrelated Kubernetes ConfigMap","Only the monthly BCM user report"],"explain":"Hardware error isolation decisions require correlated event and impact evidence."},{"domain":"Troubleshooting and Optimization","stem":"GPU utilization is low while application CPU use and dataloader wait time are high. What is the most probable bottleneck to investigate?","choices":["The CPU or input pipeline supplying work to the accelerator","MIG hardware partitioning alone","Slurm accounting retention","BCM interface role names"],"explain":"Heavy CPU preprocessing or input waiting can leave accelerator compute underused."},{"domain":"Troubleshooting and Optimization","stem":"During a GPU diagnostic, DCGM reports a failing health condition. What is the safest next action?","choices":["Capture detailed diagnostics, identify the affected device, and follow the maintenance isolation procedure","Hide the alert and resume every node","Delete all application logs","Assume the device is healthy because it is visible"],"explain":"Diagnostic failures should be documented, scoped, and resolved before returning impacted devices to service."},{"domain":"Troubleshooting and Optimization","stem":"GPU communication performance dropped after a software stack update. What should be compared?","choices":["Driver, CUDA or communication-library versions, fabric metrics, and before-and-after benchmarks","Only GPU temperatures measured at idle","Only deployment labels","Only the number of user accounts"],"explain":"Regressions are investigated by comparing relevant software versions and measurable communication performance."}]];
const QB=AIO_MOCK_SETS.flatMap((set,variant)=>set.map((q,i)=>({...q,id:variant*30+i})));

const mockStore='cf-mock-v9';
function shuffle(a){let r=a.slice();for(let i=r.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]]}return r}
function buildQuestions(variant=0){let examIndex=Math.max(0,Math.min(3,Number(variant)||0));return shuffle(AIO_MOCK_SETS[examIndex].map(q=>({...q,choices:shuffle(q.choices.map((value,i)=>({value,correct:i===0})))})))}
function saveMock(){try{localStorage.setItem(mockStore,JSON.stringify(mock))}catch{}}
try{const saved=JSON.parse(localStorage.getItem(mockStore)||'null');if(saved?.version===9)mock=saved}catch{}
function remaining(){return mock?Math.max(0,7200000-(Date.now()-mock.startedAt)):7200000}
function clockText(){let s=Math.ceil(remaining()/1000);return `${Math.floor(s/3600)}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function mockScore(){let domains=DOMAINS.map(([name,weight])=>{let qs=mock.qs.map((q,i)=>({q,a:mock.answers[i]})).filter(x=>x.q.domain===name),correct=qs.filter(x=>x.a!==null&&x.q.choices[x.a]?.correct).length;return {name,weight,correct,total:qs.length,pct:qs.length?100*correct/qs.length:0}});let qPct=domains.reduce((v,d)=>v+d.pct*d.weight/100,0);let labs=mock.labResults.map((x,i)=>{let id=mock.labIds[i],g=walkthroughs[id],count=g.steps.length,earned=x?x.completed.reduce((v,done,j)=>v+(done?Math.max(0,1-(Number(x.hints[j])>=3?1:Number(x.hints[j])===2?0.75:Number(x.hints[j])===1?0.5:0)):0),0):0;return {name:g.name,earned,total:count,pct:100*earned/count,hints:x?.hints.reduce((total,uses)=>total+(Number(uses)||0),0)||0}});let labPct=labs.reduce((v,l)=>v+l.pct,0)/3;return {domains,qPct,labs,labPct,overall:(qPct+labPct)/2}}
function mockStart(variant=0){if(mock&&mock.phase!=='results'&&!confirm('Replace your current mock exam?'))return;const pool={slurm:['drain','slurm-resources','slurm-partition','slurm-gres','slurm-service'],k8s:['image','k8s-pending','k8s-crash','k8s-gpu','k8s-node'],bcm:['bcm','bcm-image','bcm-category']};let labIds=shuffle([shuffle(pool.slurm)[0],shuffle(pool.k8s)[0],shuffle(pool.bcm)[0]]);mock={version:9,variant,startedAt:Date.now(),phase:'questions',qs:buildQuestions(variant),answers:Array(30).fill(null),qIndex:0,labIds,labIndex:0,labResults:[null,null,null]};guide=null;saveMock();page='exams';render()}
window.startMock=mockStart;
window.mockAnswer=i=>{if(mock?.phase!=='questions')return;mock.answers[mock.qIndex]=i;saveMock();render()};
window.mockNav=delta=>{if(mock?.phase!=='questions')return;mock.qIndex=Math.max(0,Math.min(29,mock.qIndex+delta));saveMock();render()};
window.mockToLabs=()=>{if(mock?.phase!=='questions')return;if(mock.answers.some(a=>a===null)&&!confirm('Some questions are unanswered. Continue to labs?'))return;mock.phase='labs';startMockLab();};
function startMockLab(){if(!mock||mock.phase!=='labs')return;window.startWalkthrough(mock.labIds[mock.labIndex]);mock.labResults[mock.labIndex]={completed:Array(walkthroughs[guide.id].steps.length).fill(false),hints:Array(walkthroughs[guide.id].steps.length).fill(0)};page='exams';saveMock();render()}
function syncMockLab(){if(mock?.phase!=='labs'||!guide)return;let r=mock.labResults[mock.labIndex];for(let i=0;i<guide.at;i++)r.completed[i]=true;saveMock()}
function mockHintUsed(){if(mock?.phase!=='labs'||!guide)return;let r=mock.labResults[mock.labIndex];if(guide.at<r.hints.length)r.hints[guide.at]=Math.min(3,(Number(r.hints[guide.at])||0)+1);saveMock()}
window.submitMockLab=()=>{if(mock?.phase!=='labs')return;syncMockLab();if(guide&&guide.at<walkthroughs[guide.id].steps.length&&!confirm('Submit this lab with unfinished checklist items?'))return;mock.labIndex++;guide=null;if(mock.labIndex>=3)finishMock();else startMockLab();saveMock();render()};
function finishMock(){if(mock.phase==='results')return;mock.phase='results';mock.finishedAt=Date.now();guide=null;saveMock();const r=mockScore();const record={id:'exam-'+mock.startedAt,startedAt:new Date(mock.startedAt).toISOString(),finishedAt:new Date(mock.finishedAt).toISOString(),overall:r.overall,questionPct:r.qPct,labPct:r.labPct,passed:r.overall>=70,domains:r.domains,labs:r.labs,questionCount:30,labIds:mock.labIds};if(!examHistory.some(x=>x.id===record.id)){examHistory.unshift(record);persistExamHistory();window.CFCloud?.saveExam?.(record)}}
window.finishMockEarly=()=>{if(!mock||mock.phase==='results')return;if(!confirm('Finish the mock exam now? Unanswered questions and unfinished labs score zero.'))return;if(mock.phase==='labs')syncMockLab();finishMock();page='exams';render()};
window.clearMock=()=>{if(mock?.phase!=='results'&&!confirm('Discard the current mock exam?'))return;mock=null;guide=null;saveMock();render()};
function exams(){if(!mock)return `<div class="mock-hero"><span class="tag">NCP-AIO PRACTICE SIMULATOR</span><h1>Full mock examination</h1><p>30 randomized questions and 3 randomized hands-on labs · 120-minute shared timer · simulated grading</p><div class="grid"><div class="card"><h2>Questions · 50%</h2><p>9 Installation & Deployment, 7 Administration, 7 Workload Management, 7 Troubleshooting & Optimization. Weighted to the published 31/23/23/23 blueprint.</p></div><div class="card"><h2>Labs · 50%</h2><p>One random Slurm, Kubernetes and BCM lab. Checklist items earn credit. The first hint on a step forfeits 50% of its credit; the second brings the total loss to 75%; the third forfeits 100%.</p></div><div class="card"><h2>Pass benchmark</h2><p>70% combined practice score. This is a custom training threshold, not an NVIDIA-published cut score.</p></div></div><div class="grid">${[0,1,2,3].map(i=>`<div class="card"><h3>Mock exam ${i+1}</h3><p>30 dedicated questions with randomized order and lab selection.</p>${button('Start mock '+(i+1),`startMock(${i})`,'primary')}</div>`).join('')}</div><div class="card"><h2>Saved exam history</h2>${examHistory.length?`<div style="overflow:auto"><table class="mock-table"><thead><tr><th>Date</th><th>Overall</th><th>Questions</th><th>Labs</th><th>Result</th></tr></thead><tbody>${examHistory.map(x=>`<tr><td>${esc(new Date(x.finishedAt).toLocaleDateString())}</td><td>${Number(x.overall).toFixed(1)}%</td><td>${Number(x.questionPct).toFixed(1)}%</td><td>${Number(x.labPct).toFixed(1)}%</td><td>${x.passed?'PASS':'RETRY'}</td></tr>`).join('')}</tbody></table></div>`:'<p>No completed mock exams yet.</p>'}<p class="muted">${window.CFCloud?.user?'Signed in: cloud sync enabled':'Guest mode: results saved on this device only. Sign in with Google to sync.'}</p></div><p class="muted">${QB.length} original questions in the bank · ${Object.keys(walkthroughs).length} lab scenarios · your attempt is saved locally in this browser.</p></div>`;
if(mock.phase!=='results'&&remaining()<=0){if(mock.phase==='labs')syncMockLab();finishMock()}
if(mock.phase==='results'){let r=mockScore();return `<h1>Mock exam results</h1><p class="sub">Tyler's NCP-AIO practice assessment · NVIDIA does not publish this 70% cut score or hint deductions.</p><div class="grid"><div class="card"><div class="muted">Overall</div><div class="metric">${r.overall.toFixed(1)}%</div><h2 class="${r.overall>=70?'success':'warning'}">${r.overall>=70?'PASS':'NOT YET PASSING'}</h2></div><div class="card"><div class="muted">Questions · 50% contribution</div><div class="metric">${r.qPct.toFixed(1)}%</div><p>${(r.qPct/2).toFixed(1)} of 50 overall points</p></div><div class="card"><div class="muted">Labs · 50% contribution</div><div class="metric">${r.labPct.toFixed(1)}%</div><p>${(r.labPct/2).toFixed(1)} of 50 overall points</p></div></div><div class="card"><h2>Question domains</h2><table class="mock-table"><thead><tr><th>Domain</th><th>Weight</th><th>Correct</th><th>Accuracy</th><th>Weighted points</th></tr></thead><tbody>${r.domains.map(d=>`<tr><td>${esc(d.name)}</td><td>${d.weight}%</td><td>${d.correct}/${d.total}</td><td>${d.pct.toFixed(1)}%</td><td>${(d.pct*d.weight/100).toFixed(1)}</td></tr>`).join('')}</tbody></table></div><div class="card"><h2>Hands-on lab scoring</h2><table class="mock-table"><thead><tr><th>Lab</th><th>Steps earned</th><th>Hints</th><th>Lab score</th></tr></thead><tbody>${r.labs.map(l=>`<tr><td>${esc(l.name)}</td><td>${l.earned.toFixed(1)}/${l.total}</td><td>${l.hints}</td><td>${l.pct.toFixed(1)}%</td></tr>`).join('')}</tbody></table><p class="muted">Each lab contributes one-third of the lab section. Each step loses 50% credit after one hint, 75% after two, or 100% after three. Unfinished steps earn zero.</p></div><details class="card"><summary>Review all 30 question answers and explanations</summary>${mock.qs.map((q,i)=>`<div class="mock-review"><strong>${i+1}. ${esc(q.stem)}</strong><p class="${mock.answers[i]!==null&&q.choices[mock.answers[i]]?.correct?'success':'warning'}">Your answer: ${esc(mock.answers[i]===null?'Unanswered':q.choices[mock.answers[i]].value)} · Correct: ${esc(q.choices.find(c=>c.correct).value)}</p><p>${esc(q.explain)}</p></div>`).join('')}</details>${button('Start next mock',`startMock(${(mock.variant+1)%4})`,'primary')} ${button('Close results','clearMock()')} ${button('View saved history','clearMock()')}`}
let top=`<div class="mock-top"><div><strong>Mock exam</strong><span>${mock.phase==='questions'?'Questions · 50%':'Hands-on labs · 50%'}</span></div><div class="mock-timer" id="mock-clock">${clockText()}</div>${button('Finish early','finishMockEarly()','tiny')}</div>`;
if(mock.phase==='questions'){let i=mock.qIndex,q=mock.qs[i],answered=mock.answers.filter(x=>x!==null).length;return `${top}<div class="mock-question"><div class="flex space"><div><span class="tag">${esc(q.domain)}</span><p>Question ${i+1} of 30 · ${answered} answered</p></div><div class="mock-jump"><label for="mock-jump">Go to</label><select id="mock-jump" onchange="mockJump(this.value)">${mock.qs.map((_,j)=>`<option value="${j}" ${i===j?'selected':''}>${j+1}${mock.answers[j]!==null?' ✓':''}</option>`).join('')}</select></div></div><div class="progress"><div style="width:${answered/30*100}%"></div></div><h2>${esc(q.stem)}</h2>${q.choices.map((c,j)=>`<button class="option ${mock.answers[i]===j?'chosen':''}" onclick="mockAnswer(${j})">${String.fromCharCode(65+j)}. ${esc(c.value)}</button>`).join('')}<div class="flex space">${button('← Previous','mockNav(-1)')}${i===29?button('Continue to labs','mockToLabs()','primary'):button('Next →','mockNav(1)','primary')}</div>${i!==29?button('Skip to labs when ready','mockToLabs()','tiny'):''}</div>`}
return `${top}<div class="mock-lab-heading"><span class="tag">Lab ${mock.labIndex+1} of 3</span><strong>${esc(walkthroughs[mock.labIds[mock.labIndex]].name)}</strong><span>Hint penalties: 1st −50%, 2nd −75% total, 3rd −100%</span></div>${terminal()}`}
window.mockJump=n=>{if(mock?.phase==='questions'){mock.qIndex=Number(n);saveMock();render()}};
window.addEventListener('pagehide',saveMock);
setInterval(()=>{if(!mock||mock.phase==='results')return;let el=document.getElementById('mock-clock');if(el)el.textContent=clockText();if(remaining()<=0){if(mock.phase==='labs')syncMockLab();finishMock();if(page==='exams')render()}},1000);
window.CFApp={
  localSnapshot:()=>({completed:[...state.completed],labHistory:[...labHistory],examHistory:[...examHistory]}),
  applyCloud:(remote)=>{if(!remote)return;const existing=new Set(state.completed);for(const id of remote.completed||[])if(walkthroughs[id])existing.add(id);state.completed=[...existing];state.repairs=Math.max(state.repairs,state.completed.length);const labs=new Map(labHistory.map(x=>[x.labId,x]));for(const x of remote.labHistory||[])if(x&&walkthroughs[x.labId]&&(!labs.has(x.labId)||String(x.completedAt)>String(labs.get(x.labId).completedAt)))labs.set(x.labId,x);labHistory=[...labs.values()];const exams=new Map(examHistory.map(x=>[x.id,x]));for(const x of remote.examHistory||[])if(x&&x.id&&!exams.has(x.id))exams.set(x.id,x);examHistory=[...exams.values()].sort((a,b)=>String(b.finishedAt).localeCompare(String(a.finishedAt)));persistLabHistory();persistExamHistory();save();render()},
  resetForAccount:()=>{state.completed=[];state.repairs=0;labHistory=[];examHistory=[];persistLabHistory();persistExamHistory();save();render()},
  render:()=>render()
};
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));render();
